#include "sketch.generated.cpp"
std::string hex(const std::string&s){const char*h="0123456789abcdef";std::string r;for(unsigned char c:s){r+=h[c>>4];r+=h[c&15];}return r;}
std::string unhex(std::string s){std::string r;if(s=="-")return r;for(size_t i=0;i+1<s.size();i+=2)r+=char(std::stoi(s.substr(i,2),nullptr,16));return r;}
const Melody* eventMelody(int e){switch(e){case EVT_START:return &melStart;case EVT_WIN:case EVT_BONUS_START:return &melWin;case EVT_LOSE:return &melLose;case EVT_MISTAKE:return &melMistake;case EVT_HIT_SUCCESS:return &melHit;case EVT_SHOT_BLUE:return &melShotBlue;case EVT_SHOT_RED:return &melShotRed;case EVT_SHOT_GREEN:return &melShotGreen;case EVT_SHOT_WHITE:case EVT_BONUS_WAVE:return &melShotWhite;case EVT_SHOT_YELLOW:return &melShotY;case EVT_SHOT_MAGENTA:return &melShotM;case EVT_SHOT_CYAN:return &melShotC;case EVT_FINAL_WIN:return &melFinalWin;case EVT_BONUS_SPEEDUP:return &melSpeedUp;case EVT_BLOCKED:return &melBlocked;case EVT_DANGER:return &melDanger;case EVT_SHIELD:return &melShield;default:return nullptr;}}
void snapshot(){const char*names[]={"MENU","INTRO","PLAYING","BOSS","LEVEL CLEARED","VICTORY","BASE DESTROYED","GAME OVER","BONUS INTRO","BEAT SABER","SIMON SAYS","TRAINING"};
std::cout<<"{\"state\":\""<<names[currentState]<<"\",\"time\":"<<clockMs<<",\"level\":"<<currentLevel<<",\"boss\":"<<currentBossType<<",\"bossPhase\":"<<(currentBossType==2?int(boss2State):int(boss3State))<<",\"score\":"<<currentScore<<",\"shield\":"<<shieldPoints<<",\"shieldMax\":"<<MAX_SHIELD<<",\"shieldRecovering\":"<<shieldRecovering()<<",\"highscore\":"<<highScore<<",\"shots\":"<<stat_totalShots<<",\"kills\":"<<stat_totalKills<<",\"front\":"<<(currentState==STATE_TRAINING?trainingFront:enemyFrontIndex)<<",\"enemies\":"<<enemies.size()<<",\"segments\":"<<bossSegments.size()<<",\"projectiles\":"<<bossProjectiles.size()<<",\"simonStage\":"<<simonStage<<",\"simonPhase\":"<<int(simonState)<<",\"simonLives\":"<<simonLives<<",\"bonusLives\":"<<bonusLives<<",\"wifi\":"<<wifiMode<<",\"brightness\":"<<FastLED.brightness<<",\"sound\":"<<config_sound_on<<",\"volume\":"<<config_volume_pct<<",\"restart\":"<<restarting<<",\"count\":"<<config_num_leds<<",\"offset\":"<<ledStartOffset<<",\"leds\":[";
for(size_t i=0;i<FastLED.frame.size();i++){if(i)std::cout<<',';auto c=FastLED.frame[i];std::cout<<'['<<int(c.r)<<','<<int(c.g)<<','<<int(c.b)<<']';}std::cout<<"],\"events\":[";
for(size_t i=0;i<soundEvents.size();i++){if(i)std::cout<<',';const Melody*m=eventMelody(soundEvents[i]);std::cout<<"{\"id\":"<<soundEvents[i]<<",\"notes\":[";if(m)for(size_t j=0;j<m->size();j++){if(j)std::cout<<',';std::cout<<'['<<(*m)[j].freq<<','<<(*m)[j].duration<<']';}std::cout<<"]}";}soundEvents.clear();std::cout<<"],\"trainingStage\":"<<trainingStage<<",\"trainingTarget\":"<<trainingTargetColor<<",\"trainingPromptHex\":\""<<hex(trainingPrompt())<<"\",\"feedbackHex\":\""<<hex(feedbackText)<<"\",\"feedbackKind\":"<<int(feedbackKind)<<",\"feedbackActive\":"<<((long)(feedbackUntil-millis())>0)<<",\"danger\":"<<baseInDanger<<",\"http\":{\"code\":"<<server.code<<",\"body\":\""<<hex(server.body)<<"\",\"type\":\""<<server.type<<"\",\"location\":\""<<hex(server.location)<<"\"}}"<<std::endl;server.body="";server.location="";}
int main(int argc,char**argv){Preferences::file=argc>1?argv[1]:"preferences.txt";Preferences::load();try{setup();}catch(Reboot&){return 75;}snapshot();std::string line;while(std::getline(std::cin,line)){std::istringstream in(line);std::string cmd;in>>cmd;try{if(cmd=="tick"){int ms,mask;in>>ms>>mask;buttonMask=mask;for(int i=0;i<std::clamp(ms,0,5000);i++){clockMs++;loop();}}
else if(cmd=="scene"){int n;in>>n;buttonMask=0;wifiMode=false;buttonsReleased=true;btnWhiteHeld=false;isWaitingForCombo=false;shots.clear();enemies.clear();bossSegments.clear();bossProjectiles.clear();bonusPlayedThisLevel=false;autoBonusTrigger=false;currentScore=0;levelStartTime=clockMs;if(n==102){startTraining();}else if(n==100){bonusReturnLevel=2;startBonusGame();}else if(n==101){bonusReturnLevel=2;startSimonBonus();}else if(n>=1&&n<=11){resetShield();startLevelIntro(n);}}
else if(cmd=="http"){std::string path;int n;in>>path>>n;server.args.clear();for(int i=0;i<n;i++){std::string k,v;in>>k>>v;server.args[unhex(k)]=unhex(v);}server.request(unhex(path));}
}catch(Reboot&){snapshot();return 75;}snapshot();}}
